@CrossOrigin
@RestController
@RequestMapping("/CatalogQuery")
public class CatalogQueryRestController extends BaseSpringRestController {
	
	public CatalogQueryRestController( CatalogService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Catalog using a UUID
     * @param		UUID catalogId
     * @return		Catalog
     */    
    @GetMapping("/load")
    public Catalog load( @RequestParam(required=true) UUID catalogId ) {
    	Catalog entity = null;

    	try {  
    		entity = service.getCatalog( new CatalogFetchOneSummary( catalogId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Catalog using Id " + catalogId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Catalog business objects
     * @return		Set<Catalog>
     */
    @GetMapping("/")
    public List<Catalog> loadAll() {                
    	List<Catalog> catalogList = null;
        
    	try {
            // load the Catalog
            catalogList = service.getAllCatalog();
            
            if ( catalogList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Catalogs" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Catalogs ", exc );
        	return null;
        }

        return catalogList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Catalog catalog = null;
    protected CatalogService service = null;
    private static final Logger LOGGER = Logger.getLogger(CatalogQueryRestController.class.getName());
    
}
